/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('identity')` (or `ctx.tryUse` for an optional dependency). */
export interface IdentityPublicApi {
  /** Verify an access token and return who is calling. Used by the kernel HTTP layer for every area; seller principals carry the chosen sellerId and memberId. Used by: kernel. */
  authenticate(accessToken: string): Promise<Principal | null>;
  /** Validate the X-Guest-Session header and touch its expiry Used by: kernel, cart, checkout, customers. */
  verifyGuestSession(guestSessionId: string): Promise<GuestSession | null>;
  /** Email, display name, status, 2-step state Used by: customers, sellers, access, notifications, audit, support. */
  getAccount(accountId: string): Promise<AccountSummary | null>;
  /** Batch lookup for lists (staff directory, seller members, audit names) Used by: access, sellers, audit, notifications. */
  getAccounts(accountIds: string[]): Promise<AccountSummary[]>;
  /** Used when inviting someone who may already have an account Used by: sellers, access. */
  findAccountByEmail(email: string, realm: 'member' | 'staff'): Promise<AccountSummary | null>;
  /** Create an invited staff account and send the accept link (event identity.invitation.created). access assigns the roles. Used by: access. */
  inviteStaff(input: { email: string, name: string, invitedBy: common.Actor }): Promise<Invitation>;
  /** Invite a person to act for a seller. Reuses an existing member account when the email has one. Used by: sellers. */
  inviteSellerMember(input: { email: string, name: string, sellerId: string, sellerName: string, invitedBy: common.Actor }): Promise<Invitation>;
  /** Allow an account to sign in to Seller Center for this seller. Called again to refresh the label. Used by: sellers. */
  grantSellerContext(input: { accountId: string, sellerId: string, memberId: string, sellerName: string, roleLabel: string, isOwner: boolean }): Promise<void>;
  /** Remove seller access and revoke sessions bound to that seller Used by: sellers. */
  revokeSellerContext(accountId: string, sellerId: string, reason: string): Promise<void>;
  /** Sign an account out everywhere (or in one area). Returns the number of sessions revoked. Used by: access, sellers, trust. */
  revokeSessions(accountId: string, reason: string, audience?: 'store' | 'seller' | 'admin'): Promise<number>;
  /** Re-check the password or a 2-step code before a sensitive action (payout destination change, approval of a large payout) Used by: finance, access. */
  verifyStepUp(accountId: string, proof: { password?: string, code?: string }): Promise<boolean>;
  /** Let a guest session open one order (after guest checkout, a successful lookup in customers, or an emailed link) Used by: checkout, customers. */
  grantGuestOrderAccess(guestSessionId: string, orderId: string, email: string, via: 'checkout' | 'lookup' | 'link'): Promise<GuestSession>;
  /** Gate guest access to order detail, tracking, returns and help Used by: orders, shipping, returns, support, customers, media. */
  hasGuestOrderAccess(guestSessionId: string, orderId: string): Promise<boolean>;
  /** Signed link for confirmation and 'email me my order links' emails; redeemed at POST /api/public/identity/order-links/{token}/redeem Used by: checkout, customers, notifications. */
  issueOrderLink(orderId: string, email: string): Promise<{ url: string, expiresAt: string }>;
  /** Close the member credential after customers completes a closure. Revokes all sessions; keeps Seller Center access if the account still belongs to a seller. Used by: customers. */
  closeAccount(accountId: string, reason: string): Promise<void>;
  /** Staff-initiated reset from another module's screen (customers account actions) Used by: customers. */
  sendPasswordReset(accountId: string, input: { reason: string, by: common.Actor, revokeSessions: boolean }): Promise<void>;
  /** Text a 6-digit code to a new mobile number (needs SMS, phase 2; until then the number stays unverified). Confirmed at POST /api/public/identity/verifications/{id}/confirm; publishes identity.user.verified with channel phone. Used by: customers. */
  startPhoneVerification(accountId: string, phone: string): Promise<VerificationChallenge>;
  /** True when the re-auth token was issued to this account, session, audience and seller for this purpose, is unused and unexpired. Does not consume it. Used by: customers, sellers, finance. */
  verifyReauthToken(principal: Principal, token: string, purpose: string): Promise<boolean>;
  /** Batched staff view of sign-in security for customer 360 views: AccountAdmin (lock, forced reset, 2-step, devices, recent security activity) plus email status, warnings and a one-line sign-in summary. Callers pass identity account ids (Customer.userId). Used by: graphql. */
  accountSecurityOf(accountIds: string[], opts?: { activityLimit?: number }): Promise<Map<string, unknown>>;
  /** Marks a verified re-auth token used; called by the kernel after the request succeeded. Used by: kernel. */
  consumeReauthToken(token: string): Promise<void>;
  /** Revoked sessions and account-wide revocations (tokens issued before validAfter) since a cursor; every server polls this every few seconds and loads the last access-token lifetime on startup. Used by: kernel. */
  revocationsSince(cursor?: string): Promise<{ sessions: { sessionId: string, at: string }[], accounts: { accountId: string, validAfter: string }[], cursor: string }>;
  /** Middleware check for refresh and sign-out: the session the refresh token belongs to (also during the reuse grace window), or null when it is unknown, expired, revoked or reused. Used by: kernel. */
  verifyRefreshToken(refreshToken: string): Promise<{ sessionId: string, accountId?: string, audience: string, kind: string } | null>;
}

/* ------------------------------------------------------------------ tables (Kysely row types) */

/** Tables in the `identity` schema. Use with `ctx.db` (already scoped to the schema). */
export interface IdentityDb {
  /** One row per account. Email is unique per realm (the same person can have a member account and a staff account). */
  accounts: {
    id: string;
    realm: 'member' | 'staff';
    email: string;
    email_normalized: string;
    email_verified_at: Date | null;
    display_name: string;
    status: string;
    /** argon2id */
    password_hash: string | null;
    password_changed_at: Date | null;
    must_reset_password: boolean;
    failed_sign_ins: number;
    failed_window_started_at: Date | null;
    locked_until: Date | null;
    lock_reason: string | null;
    locked_by: string | null;
    closed_at: Date | null;
    accepted_terms_version: string | null;
    created_at: Date;
    last_sign_in_at: Date | null;
    last_active_at: Date | null;
    version: number;
    tokens_valid_after: Date | null;
  };
  /** Last N hashes to block reuse */
  password_history: {
    id: string;
    account_id: string;
    password_hash: string;
    created_at: Date;
  };
  two_step_methods: {
    id: string;
    account_id: string;
    method: 'totp' | 'sms';
    secret_encrypted: Uint8Array | null;
    phone_e164_encrypted: Uint8Array | null;
    phone_masked: string | null;
    confirmed_at: Date | null;
    last_used_at: Date | null;
    /** TOTP replay guard */
    last_used_step: number | null;
    removed_at: Date | null;
  };
  recovery_codes: {
    id: string;
    account_id: string;
    code_hash: string;
    batch_id: string;
    used_at: Date | null;
  };
  /** Email verification, email change, phone verification, 2-step sign-in and 2-step setup challenges */
  challenges: {
    id: string;
    account_id: string | null;
    purpose: 'email_verification' | 'email_change' | 'phone_verification' | 'sign_in_second_factor' | 'two_step_setup';
    target_email: string | null;
    code_hash: string | null;
    /** setup secret, pending session request */
    payload: Json;
    attempts: number;
    max_attempts: number;
    status: string;
    expires_at: Date;
    resend_available_at: Date | null;
    created_at: Date;
    completed_at: Date | null;
    target_phone_encrypted: Uint8Array | null;
  };
  password_resets: {
    id: string;
    account_id: string;
    token_hash: string;
    forced_by: string | null;
    forced_reason: string | null;
    expires_at: Date;
    used_at: Date | null;
    requested_ip: string | null;
    created_at: Date;
  };
  /** A browser or app install seen for an account */
  devices: {
    id: string;
    account_id: string;
    kind: 'web' | 'android';
    label: string;
    installation_id: string | null;
    user_agent: string | null;
    app_version: string | null;
    last_ip: string | null;
    last_location: string | null;
    two_step_trusted_until: Date | null;
    first_seen_at: Date;
    last_active_at: Date;
  };
  /** One per sign-in. Refresh tokens rotate inside a session (family); reuse of a rotated token revokes the session. */
  sessions: {
    id: string;
    account_id: string;
    device_id: string;
    audience: 'store' | 'seller' | 'admin';
    seller_id: string | null;
    seller_member_id: string | null;
    refresh_token_hash: string;
    previous_token_hash: string | null;
    keep_signed_in: boolean;
    two_step_verified_at: Date | null;
    created_at: Date;
    last_refreshed_at: Date;
    expires_at: Date;
    absolute_expires_at: Date;
    revoked_at: Date | null;
    revoke_reason: string | null;
  };
  /** Sellers an account may act for. Written only by the sellers module through grantSellerContext / revokeSellerContext. */
  seller_access: {
    account_id: string;
    seller_id: string;
    seller_member_id: string;
    seller_name: string;
    role_label: string;
    is_owner: boolean;
    granted_at: Date;
    revoked_at: Date | null;
    last_used_at: Date | null;
  };
  invitations: {
    id: string;
    realm: string;
    purpose: 'staff' | 'seller_member';
    email: string;
    name: string;
    account_id: string | null;
    context_ref: string | null;
    context_label: string | null;
    token_hash: string;
    invited_by_kind: string;
    invited_by_id: string;
    status: string;
    sent_at: Date;
    expires_at: Date;
    accepted_at: Date | null;
    revoked_at: Date | null;
    revoke_reason: string | null;
  };
  /** Visitor sessions (auth v3): one per app install before sign-in; in the store also the guest session */
  guest_sessions: {
    id: string;
    device_kind: string;
    created_at: Date;
    last_seen_at: Date;
    expires_at: Date;
    claimed_by_account_id: string | null;
    claimed_at: Date | null;
    audience: 'store' | 'seller' | 'admin';
    refresh_token_hash: string;
    previous_token_hash: string | null;
    rotated_at: Date | null;
  };
  /** Orders a guest session may open */
  guest_order_grants: {
    guest_session_id: string;
    order_id: string;
    email_normalized: string;
    via: 'checkout' | 'lookup' | 'link';
    granted_at: Date;
    expires_at: Date;
  };
  /** Emailed order links (token hash only) */
  order_links: {
    id: string;
    token_hash: string;
    order_id: string;
    email_normalized: string;
    expires_at: Date;
    last_redeemed_at: Date | null;
    redeem_count: number;
  };
  /** Per-account security activity (append-only) */
  security_events: {
    id: string;
    account_id: string;
    kind: string;
    result: string;
    audience: string | null;
    device_id: string | null;
    device_label: string | null;
    ip: string | null;
    location: string | null;
    actor_kind: string | null;
    actor_id: string | null;
    reason: string | null;
    detail: Json;
    at: Date;
  };
  /** Rate limiting by email and IP, including unknown emails */
  sign_in_attempts: {
    id: Generated<number>;
    email_normalized: string;
    ip: string;
    succeeded: boolean;
    at: Date;
  };
  /** Short-lived proof of a recent password or 2-step check */
  reauth_tokens: {
    token_hash: string;
    account_id: string;
    session_id: string;
    expires_at: Date;
    used_at: Date | null;
  };
}

